-- Generated by scripts/generate-portal-migration.js from the shared category rules.
-- Existing student records stay in erp. No table is exposed through the Data API.
-- Only this narrow RPC is exposed; JWT identity is checked before every read.
CREATE FUNCTION erp.cgpa_category(value numeric) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  SELECT CASE WHEN (a.cgpa BETWEEN '0'::numeric AND '10'::numeric) THEN CASE WHEN a.cgpa >= '8.50'::numeric THEN 'advanced'::text WHEN a.cgpa >= '6.75'::numeric THEN 'medium'::text ELSE 'needs-improvement'::text END ELSE NULL END FROM (SELECT value AS cgpa) a
$$;
CREATE FUNCTION erp.cgpa_rules() RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT '[{"id":"advanced","name":"Advanced","minimum":"8.50","displayRange":"8.50 and above","conditionLabel":"8.50 and above"},{"id":"medium","name":"Medium","minimum":"6.75","displayRange":"6.75 – 8.49","conditionLabel":"6.75 to below 8.50"},{"id":"needs-improvement","name":"Needs Improvement","minimum":null,"displayRange":"Below 6.75","conditionLabel":"Below 6.75"}]'::jsonb $$;
CREATE FUNCTION erp.cgpa_scale() RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT '{"min":"0","max":"10"}'::jsonb $$;
CREATE FUNCTION erp.cgpa_bands() RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT '[{"id":"under-six","label":"Below 6.0","lower":null,"upper":"6"},{"id":"six-seven","label":"6.0 to below 7.0","lower":"6","upper":"7"},{"id":"seven-eight","label":"7.0 to below 8.0","lower":"7","upper":"8"},{"id":"eight-nine","label":"8.0 to below 9.0","lower":"8","upper":"9"},{"id":"nine-ten","label":"9.0 and above","lower":"9","upper":null}]'::jsonb $$;

CREATE FUNCTION erp.portal_cohort(q jsonb)
RETURNS TABLE(id uuid,enrollment_no text,full_name text,department_short_name text,source_batch text,cgpa numeric,category_id text)
LANGUAGE sql STABLE SET search_path = '' AS $$
  SELECT s.id,s.enrollment_no,s.full_name,s.department_short_name,s.source_batch,
    a.cgpa,erp.cgpa_category(a.cgpa)
  FROM erp.students s LEFT JOIN erp.academics a ON a.student_id=s.id
  WHERE (NULLIF(q->>'batch','') IS NULL OR s.source_batch=q->>'batch')
    AND (NULLIF(q->>'department','') IS NULL
      OR (q->>'department'='__missing__' AND s.department_short_name IS NULL)
      OR s.department_short_name=q->>'department')
    AND (COALESCE(q->>'search','')='' OR strpos(lower(s.full_name),lower(q->>'search'))>0
      OR strpos(lower(s.enrollment_no),lower(q->>'search'))>0)
$$;

CREATE FUNCTION erp.portal_summary(q jsonb) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = '' AS $$
  WITH cohort AS MATERIALIZED (SELECT * FROM erp.portal_cohort(q)),
  totals AS (SELECT count(*) AS total,count(*) FILTER(WHERE category_id IS NOT NULL) AS valid,
    count(*) FILTER(WHERE cgpa IS NULL) AS missing,
    count(*) FILTER(WHERE cgpa IS NOT NULL AND category_id IS NULL) AS invalid,
    (avg(cgpa) FILTER(WHERE category_id IS NOT NULL))::text AS average FROM cohort)
  SELECT jsonb_build_object('total',total,'valid',valid,'missing',missing,'invalid',invalid,
    'unclassified',missing+invalid,'averageCgpa',average,'scale',erp.cgpa_scale(),
    'placementPolicy',jsonb_build_object('configured',false),
    'categories',(SELECT jsonb_agg(r.rule || jsonb_build_object('count',c.n,
      'percentage',CASE WHEN t.total=0 THEN 0 ELSE 100.0*c.n/t.total END,
      'averageCgpa',c.average,'eligibleCount',NULL,'eligibilityPercentage',NULL) ORDER BY r.ord)
      FROM jsonb_array_elements(erp.cgpa_rules()) WITH ORDINALITY r(rule,ord)
      CROSS JOIN LATERAL (SELECT count(*) AS n,avg(cgpa)::text AS average FROM cohort WHERE category_id=r.rule->>'id') c),
    'distribution',(SELECT jsonb_agg(jsonb_build_object('id',b.band->>'id','label',b.band->>'label',
      'count',c.n,'percentage',CASE WHEN t.total=0 THEN 0 ELSE 100.0*c.n/t.total END) ORDER BY b.ord)
      FROM jsonb_array_elements(erp.cgpa_bands()) WITH ORDINALITY b(band,ord)
      CROSS JOIN LATERAL (SELECT count(*) AS n FROM cohort WHERE category_id IS NOT NULL
        AND (b.band->>'lower' IS NULL OR cgpa >= (b.band->>'lower')::numeric)
        AND (b.band->>'upper' IS NULL OR cgpa < (b.band->>'upper')::numeric)) c)) FROM totals t
$$;

CREATE FUNCTION public.dsu_portal_read(request_path text, query jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' SET statement_timeout = '15s' AS $$
DECLARE
  -- PostgREST verifies the JWT and sets these claims; request parameters cannot set them.
  actor uuid := (NULLIF(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid;
  access_record record;
  payload jsonb;
  summary jsonb;
  options jsonb;
  category jsonb;
  selected_category text;
  selected_student uuid;
  student_record jsonb;
  academic jsonb;
  contact jsonb := NULL;
  fees jsonb := NULL;
  students jsonb;
  batch_rows jsonb;
  n integer;
  page_no integer := 1;
  page_size integer := 25;
  is_export boolean := false;
  search_text text;
BEGIN
  IF actor IS NULL THEN RAISE SQLSTATE 'PT401' USING MESSAGE='Sign in to continue.'; END IF;
  -- Never trust caller-supplied identity or role, including app.user_id left by another call.
  PERFORM set_config('app.user_id',actor::text,true);
  SELECT role,student_id INTO access_record FROM erp.memberships WHERE user_id=actor;
  IF NOT FOUND THEN RAISE SQLSTATE 'PT403' USING MESSAGE='Your account does not have access.'; END IF;
  IF query IS NULL OR jsonb_typeof(query)<>'object' OR octet_length(query::text)>4096
    OR EXISTS(SELECT 1 FROM jsonb_each(query) p WHERE p.key NOT IN ('batch','department','search','page','limit') OR jsonb_typeof(p.value)<>'string')
    OR (query ? 'batch' AND query->>'batch' !~ '^20[0-9]{2}$')
    OR (query ? 'department' AND length(query->>'department') NOT BETWEEN 1 AND 200)
    OR length(COALESCE(query->>'search',''))>100
    OR (query ? 'page' AND query->>'page' !~ '^[0-9]{1,6}$')
    OR (query ? 'limit' AND query->>'limit' !~ '^[0-9]{1,3}$') THEN
    RAISE SQLSTATE 'PT400' USING MESSAGE='Invalid filters.';
  END IF;
  page_no := COALESCE((query->>'page')::integer,1);
  page_size := COALESCE((query->>'limit')::integer,25);
  IF page_no NOT BETWEEN 1 AND 100000 OR page_size NOT BETWEEN 1 AND 100 THEN
    RAISE SQLSTATE 'PT400' USING MESSAGE='Invalid pagination.';
  END IF;

  IF request_path='/me' THEN
    RETURN jsonb_build_object('data',jsonb_build_object('id',actor,'role',access_record.role,'studentId',access_record.student_id));
  ELSIF request_path ~ '^/students/[0-9a-fA-F-]{36}$' THEN
    BEGIN selected_student := split_part(request_path,'/',3)::uuid;
    EXCEPTION WHEN invalid_text_representation THEN RAISE SQLSTATE 'PT404' USING MESSAGE='Student not found.'; END;
    SELECT to_jsonb(s) INTO student_record FROM (SELECT id,enrollment_no,full_name,display_no,course_name,
      department_name,current_semester,current_batch,current_division,status,source_batch FROM erp.students WHERE id=selected_student) s;
    IF student_record IS NULL THEN RAISE SQLSTATE 'PT404' USING MESSAGE='Student not found.'; END IF;
    SELECT to_jsonb(a) INTO academic FROM (SELECT attendance::text,achievements,cgpa::text,percentage::text,
      sgpa::text,current_backlog,total_backlog FROM erp.academics a WHERE a.student_id=selected_student) a;
    IF access_record.role<>'staff' THEN
      SELECT c.details INTO contact FROM erp.contacts c WHERE c.student_id=selected_student;
      SELECT to_jsonb(a) INTO fees FROM (SELECT fees_paid::text,fees_outstanding::text,fee_category FROM erp.academics a WHERE a.student_id=selected_student) a;
    END IF;
    payload := jsonb_build_object('data',student_record || jsonb_build_object('academic',academic,'contact',contact,'fees',fees));
  ELSE
    IF access_record.role NOT IN ('admin','staff') THEN RAISE SQLSTATE 'PT403' USING MESSAGE='Access denied.'; END IF;
    IF request_path='/overview' THEN
      SELECT jsonb_build_object('students',count(*),'departments',count(DISTINCT department_short_name),'batches',count(DISTINCT source_batch),
        'departmentBreakdown',(SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::jsonb) FROM
          (SELECT department_short_name AS name,count(*) AS students FROM erp.students GROUP BY 1 ORDER BY 2 DESC,1) d))
      INTO payload FROM erp.students;
      payload := jsonb_build_object('data',payload);
    ELSIF request_path='/imports' THEN
      IF access_record.role<>'admin' THEN RAISE SQLSTATE 'PT403' USING MESSAGE='Access denied.'; END IF;
      SELECT jsonb_build_object('data',COALESCE(jsonb_agg(to_jsonb(r)),'[]'::jsonb)) INTO payload FROM
        (SELECT i.id,i.source_batch,i.summary,i.created_at FROM erp.import_runs i ORDER BY i.created_at DESC LIMIT 20) r;
    ELSIF request_path='/students' THEN
      search_text := lower(COALESCE(query->>'search',''));
      SELECT count(*) INTO n FROM erp.students s WHERE
        (starts_with(lower(s.full_name),search_text) OR starts_with(lower(s.enrollment_no),search_text))
        AND (query->>'batch' IS NULL OR s.source_batch=query->>'batch');
      SELECT COALESCE(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO students FROM
        (SELECT s.id,s.enrollment_no,s.full_name,s.department_short_name,s.source_batch,s.current_semester,s.status,
          a.cgpa::text,a.attendance::text,erp.cgpa_category(a.cgpa) AS category_id,
          (SELECT rule FROM jsonb_array_elements(erp.cgpa_rules()) rule WHERE rule->>'id'=erp.cgpa_category(a.cgpa)) AS category
        FROM erp.students s LEFT JOIN erp.academics a ON a.student_id=s.id WHERE
          (starts_with(lower(s.full_name),search_text) OR starts_with(lower(s.enrollment_no),search_text))
          AND (query->>'batch' IS NULL OR s.source_batch=query->>'batch')
        ORDER BY s.enrollment_no COLLATE "C",s.id LIMIT page_size OFFSET (page_no-1)*page_size) r;
      payload := jsonb_build_object('data',students,'pagination',jsonb_build_object('total',n,'page',page_no,'limit',page_size));
    ELSIF request_path IN ('/analytics','/batch-analytics','/student-categories')
      OR request_path ~ '^/student-categories/(advanced|medium|needs-improvement)(/export)?$' THEN
      is_export := right(request_path,7)='/export';
      IF is_export AND access_record.role<>'admin' THEN RAISE SQLSTATE 'PT403' USING MESSAGE='Access denied.'; END IF;
      summary := erp.portal_summary(query);
      SELECT jsonb_build_object(
        'batches',ARRAY(SELECT DISTINCT source_batch FROM erp.students ORDER BY source_batch DESC),
        'departments',ARRAY(SELECT DISTINCT department_short_name FROM erp.students WHERE department_short_name IS NOT NULL ORDER BY department_short_name),
        'missing_department',EXISTS(SELECT 1 FROM erp.students WHERE department_short_name IS NULL)) INTO options;
      payload := jsonb_build_object('summary',summary,'options',options,'filters',query-'page'-'limit');
      IF request_path='/batch-analytics' THEN
        WITH cohort AS MATERIALIZED (SELECT * FROM erp.portal_cohort(query))
        SELECT COALESCE(jsonb_agg(to_jsonb(b) ORDER BY b.source_batch DESC),'[]'::jsonb) INTO batch_rows FROM
          (SELECT source_batch,count(*) AS total,count(*) FILTER(WHERE category_id IS NOT NULL) AS valid,
            count(*) FILTER(WHERE category_id IS NULL) AS unclassified,
            (avg(cgpa) FILTER(WHERE category_id IS NOT NULL))::text AS average,
            count(*) FILTER(WHERE category_id='advanced') AS advanced,
            count(*) FILTER(WHERE category_id='medium') AS medium,
            count(*) FILTER(WHERE category_id='needs-improvement') AS "needs-improvement"
          FROM cohort GROUP BY source_batch) b;
        payload := payload || jsonb_build_object('batches',batch_rows);
      ELSIF request_path LIKE '/student-categories/%' THEN
        selected_category := split_part(request_path,'/',3);
        SELECT rule INTO category FROM jsonb_array_elements(erp.cgpa_rules()) rule WHERE rule->>'id'=selected_category;
        SELECT (rule->>'count')::integer INTO n FROM jsonb_array_elements(summary->'categories') rule WHERE rule->>'id'=selected_category;
        IF is_export THEN
          IF n>20000 THEN RAISE SQLSTATE 'PT413' USING MESSAGE='Narrow the selection to at most 20,000 students.'; END IF;
          -- Preserve the previous five exports/minute policy even when bypassing Render.
          PERFORM pg_advisory_xact_lock(hashtext('erp.portal.export'),hashtext(actor::text));
          IF (SELECT count(*) FROM erp.audit_events WHERE actor_id=actor AND action='category.export'
            AND created_at>now()-interval '1 minute')>=5 THEN
            RAISE SQLSTATE 'PT429' USING MESSAGE='Please wait before exporting again.';
          END IF;
        END IF;
        page_no := least(page_no,greatest(1,ceil(n::numeric/page_size)::integer));
        WITH ranked AS (SELECT c.*,rank() OVER(ORDER BY c.cgpa DESC)::integer AS rank
          FROM erp.portal_cohort(query) c WHERE c.category_id=selected_category)
        SELECT COALESCE(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO students FROM
          (SELECT id,enrollment_no,full_name,department_short_name,source_batch,cgpa::text,category_id,rank FROM ranked
           ORDER BY ranked.cgpa DESC,enrollment_no COLLATE "C",id
           LIMIT CASE WHEN is_export THEN 20000 ELSE page_size END OFFSET CASE WHEN is_export THEN 0 ELSE (page_no-1)*page_size END) r;
        payload := payload || jsonb_build_object('category',category,'students',students,
          'pagination',jsonb_build_object('total',n,'page',page_no,'limit',page_size));
      END IF;
      payload := jsonb_build_object('data',payload);
    ELSE
      RAISE SQLSTATE 'PT404' USING MESSAGE='Resource not found.';
    END IF;
  END IF;
  INSERT INTO erp.audit_events(actor_id,action,resource_id)
    VALUES(actor,CASE WHEN is_export THEN 'category.export' ELSE 'portal.read' END,request_path);
  RETURN payload;
END $$;

-- The function owner is the restricted existing runtime role, not postgres:
-- all its queries continue to run under the existing row policies.


REVOKE ALL ON FUNCTION erp.cgpa_category(numeric),erp.cgpa_rules(),erp.cgpa_scale(),erp.cgpa_bands(),
  erp.portal_cohort(jsonb),erp.portal_summary(jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION erp.cgpa_category(numeric),erp.cgpa_rules(),erp.cgpa_scale(),erp.cgpa_bands(),
  erp.portal_cohort(jsonb),erp.portal_summary(jsonb) TO dsu_api;
GRANT CREATE ON SCHEMA public TO dsu_api;
ALTER FUNCTION public.dsu_portal_read(text,jsonb) OWNER TO dsu_api;
REVOKE CREATE ON SCHEMA public FROM dsu_api;
REVOKE ALL ON FUNCTION public.dsu_portal_read(text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.dsu_portal_read(text,jsonb) TO authenticated;
NOTIFY pgrst, 'reload schema';
